// Every #[tauri::command] must be listed here: tauri-plugin generates an
// allow-<command> permission for each (permissions/autogenerated/).
const COMMANDS: &[&str] = &["ping", "probe_source", "start_convert", "cancel_job", "estimate_sizes", "set_preview_files"];

fn main() {
  tauri_plugin::Builder::new(COMMANDS).build();
}
